// Global variables
let allData = [];
let filteredData = [];
let currentPage = 1;
const rowsPerPage = 50;
let sortColumn = null;
let sortDirection = 'asc';
let hasActiveFilters = false;

// Load data when page loads
document.addEventListener('DOMContentLoaded', () => {
    try {
        allData = embeddedData.data;
        filteredData = [];
        
        initializeFilters();
        hideTableInitially();
        setupEventListeners();
    } catch (error) {
        console.error('Error loading data:', error);
        document.getElementById('tableBody').innerHTML =
            '<tr><td colspan="17" class="empty-state"><h3>Error loading data</h3><p>Please check the console for details.</p></td></tr>';
    }
});

// Hide table initially
function hideTableInitially() {
    const tableContainer = document.querySelector('.table-container');
    tableContainer.innerHTML = `
        <div class="initial-message">
            <h3>Welcome to MaaS Rep Alignment Dashboard</h3>
            <p>Please select a filter or enter a search term to view data</p>
        </div>
    `;
}

// Initialize filter dropdowns with unique values
function initializeFilters() {
    const filters = {
        marketNameFilter: 'MARKET_NAME',
        coverageClientTypeFilter: 'COVE_CLIENT_TYPE_DESC',
        coverageClientSubtypeFilter: 'COV_CLIENT_SUB_TYPE_DESC',
        coverageNameFilter: 'COVERAGE_NAME',
        coverageIdFilter: 'COVERAGE_TYPE_ID',
        repFilter: 'Rep',
        techRepFilter: 'Tech Rep',
        managerFilter: 'Manager',
        techManagerFilter: 'Tech Manager'
    };

    Object.entries(filters).forEach(([filterId, fieldName]) => {
        const select = document.getElementById(filterId);
        // Clear all options except the first one (placeholder)
        const firstOption = select.options[0];
        select.innerHTML = '';
        select.appendChild(firstOption);
        
        const uniqueValues = [...new Set(allData.map(row => row[fieldName]))].filter(v => v).sort();
        
        uniqueValues.forEach(value => {
            const option = document.createElement('option');
            option.value = value;
            option.textContent = value;
            select.appendChild(option);
        });
    });
}

// Update available filter options based on current selection
function updateAvailableFilters() {
    const filters = {
        marketNameFilter: 'MARKET_NAME',
        coverageClientTypeFilter: 'COVE_CLIENT_TYPE_DESC',
        coverageClientSubtypeFilter: 'COV_CLIENT_SUB_TYPE_DESC',
        coverageNameFilter: 'COVERAGE_NAME',
        coverageIdFilter: 'COVERAGE_TYPE_ID',
        repFilter: 'Rep',
        techRepFilter: 'Tech Rep',
        managerFilter: 'Manager',
        techManagerFilter: 'Tech Manager'
    };

    // Get current filter values
    const currentFilters = {};
    Object.keys(filters).forEach(filterId => {
        currentFilters[filterId] = document.getElementById(filterId).value;
    });

    // Get data that matches current filters (excluding the filter being updated)
    Object.entries(filters).forEach(([filterId, fieldName]) => {
        const select = document.getElementById(filterId);
        const currentValue = currentFilters[filterId];
        
        // Get available data based on other filters
        const availableData = allData.filter(row => {
            return Object.entries(filters).every(([otherFilterId, otherFieldName]) => {
                if (otherFilterId === filterId) return true; // Skip current filter
                const filterValue = currentFilters[otherFilterId];
                return !filterValue || row[otherFieldName] === filterValue;
            });
        });

        // Get unique values from available data
        const availableValues = [...new Set(availableData.map(row => row[fieldName]))].filter(v => v).sort();
        
        // Update options
        const firstOption = select.options[0];
        select.innerHTML = '';
        select.appendChild(firstOption);
        
        availableValues.forEach(value => {
            const option = document.createElement('option');
            option.value = value;
            option.textContent = value;
            if (value === currentValue) {
                option.selected = true;
            }
            select.appendChild(option);
        });
    });
}

// Setup event listeners
function setupEventListeners() {
    // Search input
    document.getElementById('searchInput').addEventListener('input', debounce(applyFilters, 300));
    
    // Filter dropdowns
    const filterIds = ['marketNameFilter', 'coverageClientTypeFilter', 'coverageClientSubtypeFilter',
                       'coverageNameFilter', 'coverageIdFilter', 'repFilter', 'techRepFilter',
                       'managerFilter', 'techManagerFilter'];
    filterIds.forEach(id => {
        document.getElementById(id).addEventListener('change', () => {
            updateAvailableFilters();
            applyFilters();
        });
    });
    
    // Clear filters button
    document.getElementById('clearFilters').addEventListener('click', clearAllFilters);
    
    // Export button
    document.getElementById('exportBtn').addEventListener('click', exportToCSV);
    
    // Pagination
    document.getElementById('prevPage').addEventListener('click', () => changePage(-1));
    document.getElementById('nextPage').addEventListener('click', () => changePage(1));
    
    // Table header sorting
    document.querySelectorAll('th[data-sort]').forEach(th => {
        th.addEventListener('click', () => sortTable(th.dataset.sort));
    });
}

// Check if any filters are active
function checkActiveFilters() {
    const searchTerm = document.getElementById('searchInput').value;
    const marketName = document.getElementById('marketNameFilter').value;
    const coverageClientType = document.getElementById('coverageClientTypeFilter').value;
    const coverageClientSubtype = document.getElementById('coverageClientSubtypeFilter').value;
    const coverageName = document.getElementById('coverageNameFilter').value;
    const coverageId = document.getElementById('coverageIdFilter').value;
    const rep = document.getElementById('repFilter').value;
    const techRep = document.getElementById('techRepFilter').value;
    const manager = document.getElementById('managerFilter').value;
    const techManager = document.getElementById('techManagerFilter').value;

    return searchTerm || marketName || coverageClientType || coverageClientSubtype ||
           coverageName || coverageId || rep || techRep || manager || techManager;
}

// Apply all filters
function applyFilters() {
    hasActiveFilters = checkActiveFilters();
    
    if (!hasActiveFilters) {
        hideTableInitially();
        document.getElementById('resultsCount').textContent = 'Select a filter or search to view data';
        return;
    }

    const searchTerm = document.getElementById('searchInput').value.toLowerCase();
    const marketName = document.getElementById('marketNameFilter').value;
    const coverageClientType = document.getElementById('coverageClientTypeFilter').value;
    const coverageClientSubtype = document.getElementById('coverageClientSubtypeFilter').value;
    const coverageName = document.getElementById('coverageNameFilter').value;
    const coverageId = document.getElementById('coverageIdFilter').value;
    const rep = document.getElementById('repFilter').value;
    const techRep = document.getElementById('techRepFilter').value;
    const manager = document.getElementById('managerFilter').value;
    const techManager = document.getElementById('techManagerFilter').value;

    filteredData = allData.filter(row => {
        // Search filter - search across all fields
        const searchMatch = !searchTerm || Object.values(row).some(value =>
            String(value).toLowerCase().includes(searchTerm)
        );
        
        // Dropdown filters
        const marketNameMatch = !marketName || row.MARKET_NAME === marketName;
        const coverageClientTypeMatch = !coverageClientType || row.COVE_CLIENT_TYPE_DESC === coverageClientType;
        const coverageClientSubtypeMatch = !coverageClientSubtype || row.COV_CLIENT_SUB_TYPE_DESC === coverageClientSubtype;
        const coverageNameMatch = !coverageName || row.COVERAGE_NAME === coverageName;
        const coverageIdMatch = !coverageId || row.COVERAGE_TYPE_ID === coverageId;
        const repMatch = !rep || row.Rep === rep;
        const techRepMatch = !techRep || row['Tech Rep'] === techRep;
        const managerMatch = !manager || row.Manager === manager;
        const techManagerMatch = !techManager || row['Tech Manager'] === techManager;

        return searchMatch && marketNameMatch && coverageClientTypeMatch && coverageClientSubtypeMatch &&
               coverageNameMatch && coverageIdMatch && repMatch && techRepMatch && managerMatch && techManagerMatch;
    });

    currentPage = 1;
    showTable();
    renderTable();
    updateResultsCount();
}

// Show table container
function showTable() {
    const tableContainer = document.querySelector('.table-container');
    tableContainer.innerHTML = `
        <table id="dataTable">
            <thead>
                <tr>
                    <th data-sort="GEOGRAPHY_NAME">Geography ↕</th>
                    <th data-sort="MARKET_NAME">Market ↕</th>
                    <th data-sort="SUB_MARKET_NAME">Sub Market ↕</th>
                    <th data-sort="SALES_GROUP_NAME">Sales Group ↕</th>
                    <th data-sort="COVE_CLIENT_TYPE_DESC">Client Type ↕</th>
                    <th data-sort="BRANCH_NAME">Branch ↕</th>
                    <th data-sort="BRANCH_UNIT_NAME">Branch Unit ↕</th>
                    <th data-sort="COVERAGE_NAME">Coverage ↕</th>
                    <th data-sort="COVERAGE_TYPE_ID">Coverage ID ↕</th>
                    <th data-sort="Rep">Rep ↕</th>
                    <th data-sort="Role">Role ↕</th>
                    <th data-sort="Rep Email">Rep Email ↕</th>
                    <th data-sort="Tech Rep">Tech Rep ↕</th>
                    <th data-sort="Tech Rep Email">Tech Rep Email ↕</th>
                    <th data-sort="Manager">Manager ↕</th>
                    <th data-sort="Manager Email">Manager Email ↕</th>
                    <th data-sort="Tech Manager">Tech Manager ↕</th>
                    <th data-sort="Tech Manager Email">Tech Manager Email ↕</th>
                </tr>
            </thead>
            <tbody id="tableBody">
                <!-- Data will be populated by JavaScript -->
            </tbody>
        </table>
    `;
    
    // Re-attach sorting event listeners
    document.querySelectorAll('th[data-sort]').forEach(th => {
        th.addEventListener('click', () => sortTable(th.dataset.sort));
    });
}

// Clear all filters
function clearAllFilters() {
    document.getElementById('searchInput').value = '';
    document.querySelectorAll('select').forEach(select => select.value = '');
    initializeFilters(); // Reset all filter options
    hasActiveFilters = false;
    hideTableInitially();
    document.getElementById('resultsCount').textContent = 'Select a filter or search to view data';
}

// Render table with current page data
function renderTable() {
    const tbody = document.getElementById('tableBody');
    const startIndex = (currentPage - 1) * rowsPerPage;
    const endIndex = startIndex + rowsPerPage;
    const pageData = filteredData.slice(startIndex, endIndex);

    if (pageData.length === 0) {
        tbody.innerHTML = '<tr><td colspan="18" class="empty-state"><h3>No results found</h3><p>Try adjusting your filters or search term.</p></td></tr>';
        updatePagination();
        return;
    }

    tbody.innerHTML = pageData.map(row => `
        <tr>
            <td>${row.GEOGRAPHY_NAME || ''}</td>
            <td>${row.MARKET_NAME || ''}</td>
            <td>${row.SUB_MARKET_NAME || ''}</td>
            <td>${row.SALES_GROUP_NAME || ''}</td>
            <td>${row.COVE_CLIENT_TYPE_DESC || ''}</td>
            <td>${row.BRANCH_NAME || ''}</td>
            <td>${row.BRANCH_UNIT_NAME || ''}</td>
            <td>${row.COVERAGE_NAME || ''}</td>
            <td>${row.COVERAGE_TYPE_ID || ''}</td>
            <td>${row.Rep || ''}</td>
            <td>${row.Role || ''}</td>
            <td>${row['Rep Email'] ? `<a href="mailto:${row['Rep Email']}">${row['Rep Email']}</a>` : ''}</td>
            <td>${row['Tech Rep'] || ''}</td>
            <td>${row['Tech Rep Email'] ? `<a href="mailto:${row['Tech Rep Email']}">${row['Tech Rep Email']}</a>` : ''}</td>
            <td>${row.Manager || ''}</td>
            <td>${row['Manager Email'] ? `<a href="mailto:${row['Manager Email']}">${row['Manager Email']}</a>` : ''}</td>
            <td>${row['Tech Manager'] || ''}</td>
            <td>${row['Tech Manager Email'] ? `<a href="mailto:${row['Tech Manager Email']}">${row['Tech Manager Email']}</a>` : ''}</td>
        </tr>
    `).join('');

    updatePagination();
}

// Update results count
function updateResultsCount() {
    const count = document.getElementById('resultsCount');
    count.textContent = `Showing ${filteredData.length} of ${allData.length} records`;
}

// Update pagination controls
function updatePagination() {
    const totalPages = Math.ceil(filteredData.length / rowsPerPage);
    document.getElementById('pageInfo').textContent = `Page ${currentPage} of ${totalPages || 1}`;
    document.getElementById('prevPage').disabled = currentPage === 1;
    document.getElementById('nextPage').disabled = currentPage >= totalPages;
}

// Change page
function changePage(direction) {
    const totalPages = Math.ceil(filteredData.length / rowsPerPage);
    const newPage = currentPage + direction;
    
    if (newPage >= 1 && newPage <= totalPages) {
        currentPage = newPage;
        renderTable();
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }
}

// Sort table by column
function sortTable(column) {
    if (sortColumn === column) {
        sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
        sortColumn = column;
        sortDirection = 'asc';
    }

    filteredData.sort((a, b) => {
        let aVal = a[column] || '';
        let bVal = b[column] || '';
        
        // Convert to string for comparison
        aVal = String(aVal).toLowerCase();
        bVal = String(bVal).toLowerCase();

        if (aVal < bVal) return sortDirection === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortDirection === 'asc' ? 1 : -1;
        return 0;
    });

    // Update header indicators
    document.querySelectorAll('th[data-sort]').forEach(th => {
        if (th.dataset.sort === column) {
            th.textContent = th.textContent.split(' ')[0] + (sortDirection === 'asc' ? ' ↑' : ' ↓');
        } else {
            th.textContent = th.textContent.split(' ')[0] + ' ↕';
        }
    });

    renderTable();
}

// Export to CSV
function exportToCSV() {
    if (!hasActiveFilters || filteredData.length === 0) {
        alert('No data to export! Please apply filters first.');
        return;
    }

    const headers = ['GEOGRAPHY_NAME', 'MARKET_NAME', 'SUB_MARKET_NAME', 'SALES_GROUP_NAME',
                     'COVE_CLIENT_TYPE_DESC', 'COV_CLIENT_SUB_TYPE_DESC', 'BRANCH_NAME', 'BRANCH_UNIT_NAME',
                     'COVERAGE_NAME', 'COVERAGE_TYPE_ID', 'Rep', 'Role', 'Rep Email', 'Tech Rep', 'Tech Rep Email',
                     'Manager', 'Manager Email', 'Tech Manager', 'Tech Manager Email'];
    
    let csv = headers.join(',') + '\n';
    
    filteredData.forEach(row => {
        const values = headers.map(header => {
            const value = row[header] || '';
            // Escape quotes and wrap in quotes if contains comma
            return value.toString().includes(',') ? `"${value.replace(/"/g, '""')}"` : value;
        });
        csv += values.join(',') + '\n';
    });

    // Create download link
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `maas-rep-alignment-${new Date().toISOString().split('T')[0]}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
}

// Debounce function for search input
function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}
